-- Read-only probe (2026-11-05, private incident note). Sealed like every supabase-readonly result, so it reaches only the vault.
-- 1: the accounts probe_live_scores_round2.sql selected. 2: which UUIDs in this repo are real auth.users ids, by md5 only, so this file names nobody.
SELECT
  (SELECT json_agg(json_build_object('email', u.email, 'id8', left(u.id::text, 8), 'anon', u.is_anonymous, 'role', p.role, 'display_name', p.display_name,
          'created', u.created_at::date, 'last_sign_in', u.last_sign_in_at::date, 'confirmed', u.email_confirmed_at IS NOT NULL) ORDER BY u.created_at)
     FROM auth.users u LEFT JOIN public.profiles p ON p.id = u.id
    WHERE lower(u.email) LIKE 'berke%' OR lower(u.email) LIKE '%ustun%') AS round2_accounts,
  (SELECT json_agg(json_build_object('md5', md5(u.id::text), 'email', u.email, 'id8', left(u.id::text, 8), 'anon', u.is_anonymous, 'role', p.role, 'display_name', p.display_name,
          'created', u.created_at::date, 'last_sign_in', u.last_sign_in_at::date))
     FROM auth.users u LEFT JOIN public.profiles p ON p.id = u.id
